import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.ChTAMbUy.js";const k=JSON.parse('{"title":"Storage Administration","description":"","frontmatter":{},"headers":[],"relativePath":"1.9/admin/storage.md","filePath":"versions/1.9/admin/storage.md","lastUpdated":1791569256000}'),o={name:"1.9/admin/storage.md"};function n(r,e,l,d,h,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="storage-administration" tabindex="-1">Storage Administration <a class="header-anchor" href="#storage-administration" aria-label="Permalink to &quot;Storage Administration&quot;">​</a></h1><p>prokube uses Kubernetes storage for workspace volumes, notebook homes, databases, S3-compatible file-storage tenants, pipeline artifacts, and model-serving data. Storage behavior is deployment-specific and depends on the installed StorageClasses and CSI drivers.</p><h2 id="storageclasses" tabindex="-1">StorageClasses <a class="header-anchor" href="#storageclasses" aria-label="Permalink to &quot;StorageClasses&quot;">​</a></h2><p>Inspect the live cluster before making assumptions:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> storageclass</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pvc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span></code></pre></div><p>For each StorageClass, record:</p><ul><li>access modes supported by the provisioner;</li><li>whether volume expansion is allowed;</li><li>whether snapshots are supported;</li><li>reclaim policy;</li><li>node-local versus replicated behavior;</li><li>intended workload type.</li></ul><h2 id="local-storage" tabindex="-1">Local Storage <a class="header-anchor" href="#local-storage" aria-label="Permalink to &quot;Local Storage&quot;">​</a></h2><p>OpenEBS LocalPV and similar local-path provisioners can provide fast node-local volumes, often with class names such as <code>openebs-hostpath</code>. This is useful for small single-node deployments and temporary or easily recreated data.</p><p>Node-local storage is not portable across nodes. A pod using a <code>ReadWriteOnce</code> local volume must run on the node where the data exists. If the node is lost, the volume can be lost too unless another backup exists.</p><p>Use local storage only when the availability tradeoff is acceptable.</p><h2 id="replicated-storage" tabindex="-1">Replicated Storage <a class="header-anchor" href="#replicated-storage" aria-label="Permalink to &quot;Replicated Storage&quot;">​</a></h2><p>Mayastor/OpenEBS replicated storage can provide synchronous replicas across nodes when the deployment is configured for it. Class names vary by deployment; examples include no-redundancy and three-replica classes.</p><p>Replication improves availability for node or disk failure, but it is not backup. Replication also adds capacity and performance tradeoffs because each replica consumes storage and network bandwidth.</p><p>Use replicated storage for stateful components that need higher availability, such as databases or S3-compatible file-storage volumes, when the cluster has enough nodes and disks to support the replica count.</p><h2 id="component-usage" tabindex="-1">Component Usage <a class="header-anchor" href="#component-usage" aria-label="Permalink to &quot;Component Usage&quot;">​</a></h2><p>Typical storage choices:</p><table tabindex="0"><thead><tr><th>Component</th><th>Storage considerations</th></tr></thead><tbody><tr><td>Labs</td><td>Persistent home volumes are convenient for interactive work but can be constrained by <code>ReadWriteOnce</code> attachment.</td></tr><tr><td>Pipelines</td><td>Prefer S3-compatible file storage for artifacts and datasets instead of relying on Lab volumes.</td></tr><tr><td>MLflow</td><td>Metadata and artifacts need backup; artifact storage can grow quickly.</td></tr><tr><td>MinIO</td><td>Tenant volumes require deliberate sizing, backup, and migration planning.</td></tr><tr><td>Databases</td><td>Use storage with snapshot/backup support and predictable latency.</td></tr><tr><td>Model Serving</td><td>Large models should live in S3-compatible file storage or MLflow, with optional cache support where configured.</td></tr></tbody></table><h2 id="model-cache-pvcs" tabindex="-1">Model Cache PVCs <a class="header-anchor" href="#model-cache-pvcs" aria-label="Permalink to &quot;Model Cache PVCs&quot;">​</a></h2><p><a href="./../agentops/llm_serving.html#cache-model-weights">LLM Serving</a> caches preset model weights in workspace S3 by default. Dedicated PVC caches are off by default. To offer them, enable them in the pk-ui Helm values and allowlist each StorageClass with the access modes and sizes that users may request:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">marathon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  modelCache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    pvc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      storageClasses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fast-rwo</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          accessModes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ReadWriteOnce</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          minSize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10Gi</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          maxSize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2Ti</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          defaultSize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">100Gi</span></span></code></pre></div><p>Each cache gets its own new claim; pkui never reuses existing claims. When you choose StorageClasses and access modes:</p><ul><li>pkui does not check which access modes a StorageClass supports. List only modes that the provisioner supports.</li><li>A <code>ReadWriteOnce</code> cache can be mounted on only one node at a time, and pkui does not schedule a model&#39;s replicas onto that node. Replicas that land on other nodes cannot start. Offer a <code>ReadWriteMany</code> class if users need several replicas.</li><li>The cache Job writes as a non-root user and relies on <code>fsGroup</code> to get write access to the new volume. The CSI driver must apply <code>fsGroup</code> ownership for the listed access modes.</li><li>When a user deletes a PVC cache, pkui deletes the claim. With a <code>Retain</code> reclaim policy, the PersistentVolume and its data remain until you remove them.</li></ul><p>LLM Serving must be enabled for model caching. In GitOps deployments, set these values in the <code>pkui</code> Argo CD Application under <code>spec.source.helm.valuesObject</code> in the GitOps branch, so that the next sync does not revert them.</p><h2 id="troubleshooting-pvcs" tabindex="-1">Troubleshooting PVCs <a class="header-anchor" href="#troubleshooting-pvcs" aria-label="Permalink to &quot;Troubleshooting PVCs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>PVC remains pending</td><td>StorageClass name, provisioner health, capacity, allowed topology, and quota.</td></tr><tr><td>Pod cannot attach volume</td><td>Existing attachment to another node, <code>ReadWriteOnce</code> constraints, stale <code>VolumeAttachment</code>, or node failure.</td></tr><tr><td>Volume expansion does not apply</td><td><code>allowVolumeExpansion</code>, filesystem resize support, and whether the pod must restart.</td></tr><tr><td>Storage is slow</td><td>Underlying disk type, replication factor, node pressure, network bandwidth, and workload I/O pattern.</td></tr></tbody></table><p>Do not delete PVCs, PVs, <code>VolumeAttachment</code> resources, or storage-engine custom resources unless you administer the cluster and have confirmed the data is no longer needed or a restore path exists.</p><h2 id="destructive-disk-operations" tabindex="-1">Destructive Disk Operations <a class="header-anchor" href="#destructive-disk-operations" aria-label="Permalink to &quot;Destructive Disk Operations&quot;">​</a></h2><p>Some storage-engine recovery tasks require wiping disks or removing stale metadata. These operations are destructive and can permanently delete data for multiple workloads.</p><p>Before any disk wipe:</p><ol><li>Identify the exact node, disk, PV, PVC, and workload owners.</li><li>Confirm backup or acceptance of data loss.</li><li>Stop workloads that might write to the disk.</li><li>Record current storage-engine resources and events.</li><li>Run the storage-engine documented recovery procedure for the installed version.</li></ol><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./backup_restore.html">Backup and Restore</a></li><li><a href="./operations_runbooks.html">Operations Runbooks</a></li><li><a href="./../platform/file_storage.html">File Storage</a></li></ul>`,33)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
